// Client-side compression for a single product photo.
async function compressPhoto(source){
 const img=await new Promise((resolve,reject)=>{
  const i=new Image();
  i.onload=()=>resolve(i);
  i.onerror=()=>reject(new Error('Rasm ochilmadi. JPG/PNG/WebP rasm tanlang (HEIC bo‘lsa JPG ga aylantiring).'));
  i.src=source;
 });
 const width=img.naturalWidth||img.width,height=img.naturalHeight||img.height;
 if(!width||!height)throw Error('Rasmning o‘lchami noto‘g‘ri.');
 const preview=document.createElement('canvas');
 const ctx=preview.getContext('2d');
 if(!ctx)throw Error('Brauzer rasmni qayta ishlay olmayapti.');
 let side=Math.min(1050,Math.max(width,height)),quality=.78,image='';
 for(let pass=0;pass<22;pass++){
  const scale=Math.min(1,side/Math.max(width,height));
  preview.width=Math.max(1,Math.round(width*scale));
  preview.height=Math.max(1,Math.round(height*scale));
  ctx.fillStyle='#fff';ctx.fillRect(0,0,preview.width,preview.height);
  ctx.drawImage(img,0,0,preview.width,preview.height);
  image=preview.toDataURL('image/jpeg',quality);
  if(image.length<=180000)break;
  if(quality>.55)quality=Math.max(.55,quality-.08);
  else{side=Math.max(300,Math.floor(side*.8));quality=.73;}
 }
 if(!image.startsWith('data:image/jpeg;base64,')||image.length>180000)
  throw Error('Rasmni siqib bo‘lmadi. Boshqa rasm tanlang.');
 const h=document.createElement('canvas');h.width=9;h.height=8;
 const hc=h.getContext('2d');if(!hc)throw Error('Rasm tahlili ishlamadi.');
 hc.drawImage(preview,0,0,9,8);
 const px=hc.getImageData(0,0,9,8).data;let bits='';
 for(let y=0;y<8;y++)for(let x=0;x<8;x++){
  const a=(y*9+x)*4,b=a+4;
  const lum=k=>px[k]*.299+px[k+1]*.587+px[k+2]*.114;
  bits+=lum(a)>lum(b)?'1':'0';
 }
 const imageHash=Array.from({length:16},(_,i)=>parseInt(bits.slice(i*4,i*4+4),2).toString(16)).join('');
 return {image,imageHash};
}
async function imageData(file){
 if(!file)throw Error('Avval rasm tanlang.');
 if(file.size>25*1024*1024)throw Error('Rasm hajmi 25 MB dan oshmasin.');
 if(!file.type.startsWith('image/')&&!/\.(jpe?g|png|webp|heic|heif)$/i.test(file.name))
  throw Error('Faqat rasm faylini tanlang.');
 const url=URL.createObjectURL(file);
 try{return await compressPhoto(url)}finally{URL.revokeObjectURL(url)}
}
// Attempt durable PostgreSQL media first; safely fall back to the small JPEG
// embedded in the listing when an old Render deployment has no media endpoint.
// The JPEG is intentionally <= 180k chars, well below the JSON body limit.
async function resolveProductPhoto(src){
 if(!src || typeof src!=='string')return null;
 if(src.startsWith('/api/media/'))return src;
 if(!src.startsWith('data:image/'))throw Error('Rasm formati noto‘g‘ri. Qayta rasm tanlang.');
 const prepared=src.length>180000?(await compressPhoto(src)).image:src;
 try{
  const response=await api('/media',{method:'POST',body:{image:prepared}});
  if(response?.url?.startsWith('/api/media/'))return response.url;
  throw Error('RASM_URL_XATO');
 }catch(err){
  // The listing API accepts a compressed JPEG as a compatibility fallback.
  // Crucially, do not drop the image when media upload is unavailable.
  console.warn('Alohida media saqlash bajarilmadi, mahsulot bilan saqlash ishlatiladi:',err.message);
  return prepared;
 }
}

