function DashboardShell({children,role='buyer',active='overview',onNavigate}){const {t,user,go,mode,setMode}=useShop();const isSeller=role==='seller';const links=isSeller?[['seller','overview',LayoutDashboard,'sellerCab'],['seller','listings',Package,'myItems'],['seller','incoming',ClipboardList,'incoming'],['add','new',PlusCircle,'addListing']]:[['buyer','overview',LayoutDashboard,'buyerCab'],['buyer','orders',ClipboardList,'myOrders'],['buyer','favorites',Heart,'favorites'],['cart','cart',ShoppingCart,'cart']];return <div className="shell dashboard"><aside className="dash-aside"><div className="dashboard-user"><span className="avatar"><UserRound size={24}/></span><div><b>{user?.name}</b><small>{user?.faculty}</small></div></div><div className="sidebar-caption">{t('account')}</div>{links.map(([page,tab,Icon,label])=><button key={tab} className={active===tab?'current':''} onClick={()=>page==='seller'||page==='buyer'?onNavigate(tab):go(page)}><Icon size={18}/>{t(label)}</button>)}<div className="aside-bottom"><button onClick={()=>{setMode(isSeller?'buyer':'seller');go(isSeller?'buyer':'seller')}}><RefreshCcw size={16}/>{t('toggle')}</button></div></aside><section className="dash-body">{children}</section></div>}
function BuyerDashboard(){
 const {t,user,go,orders,favorites,items,lang,run,refresh}=useShop();const [tab,setTab]=useState('overview');
 const bought=orders.filter(o=>o.buyer===user.id);
 async function action(order,endpoint,question){
   if(question&&!window.confirm(question))return;
   await run(async()=>{await api('/orders/'+order.id+'/'+endpoint,{method:'POST',body:{}});await refresh()},t('saved'));
 }
 return <DashboardShell role="buyer" active={tab} onNavigate={setTab}>
  <Heading eyebrow={t('goBuyer')} title={tab==='orders'?t('myOrders'):tab==='favorites'?t('favorites'):t('buyerCab')} detail={t('accountHelp')}/>
  {tab==='overview'&&<div className="stats-grid"><div className="stat-card"><span><ClipboardList/></span><small>{t('myOrders')}</small><strong>{bought.length}</strong></div><div className="stat-card"><span><Heart/></span><small>{t('favorites')}</small><strong>{favorites.length}</strong></div><div className="stat-card"><span><Package/></span><small>{t('listings')}</small><strong>{items.length}</strong></div></div>}
  {(tab==='overview'||tab==='orders')&&<section className="surface spaced"><div className="panel-header"><h3>{t('myOrders')}</h3><button className="text-button" onClick={()=>go('catalog')}>{t('goCatalog')} <ArrowRight size={14}/></button></div>{bought.length?<div className="data-list">{bought.map(o=><div className="order-row shods-v4-order" key={o.id}>
   <div className="row-icon"><Package/></div><div className="order-info"><b>{o.name}</b><small>#{o.id} • {readable(o.createdAt,lang)}</small><small><MapPin size={12}/>{o.location}</small>{o.payment==='pay_on_receipt'&&<div className="v4-order-note"><ShieldCheck size={14}/>{o.paymentStatus==='paid'?delivery(lang,'paid'):delivery(lang,'unpaid')}</div>}</div>
   <div className="order-meta"><b>{money(o.total,lang)}</b><small>{t('qty')}: {o.qty}</small><span className={'status status-'+o.status}>{orderStatus(o,t,lang)}</span>
    {o.payment==='pay_on_receipt'&&<div className="v4-order-actions">
      {o.status==='handed_over'&&<button className="button primary small" onClick={()=>action(o,'receive',delivery(lang,'confirmReceipt'))}><Package size={15}/>{delivery(lang,'receivedBtn')}</button>}
      {o.status==='received'&&o.paymentStatus!=='paid'&&<small className="shods-cash-hint"><Wallet size={15}/>{delivery(lang,'cashWaitSeller')}</small>}
      {o.status==='completed'&&o.paymentStatus==='paid'&&<span className="v4-paid-stamp"><CheckCircle2 size={15}/>{delivery(lang,'paid')}</span>}
    </div>}
   </div>
  </div>)}</div>:<div className="empty-slim">{t('noOrders')}</div>}</section>}
  {tab==='favorites'&&<ItemsGrid list={items.filter(x=>favorites.includes(x.id))}/>}</DashboardShell>
}
function SellerDashboard(){
 const {t,user,go,items,mine,refresh,run,orders,lang}=useShop();const [tab,setTab]=useState(nativeApp?'incoming':'overview');
 const sellers=orders.filter(o=>o.seller===user.id).sort((a,b)=>Number(a.status==='completed')-Number(b.status==='completed')||new Date(b.createdAt)-new Date(a.createdAt));const completed=sellers.filter(x=>x.status==='completed');
 async function status(o,next){await run(async()=>{await api('/orders/'+o.id,{method:'PATCH',body:{status:next}});await refresh()},t('saved'))}
 async function settleCash(o){if(!window.confirm(delivery(lang,'cashConfirmAsk')))return;await run(async()=>{await api('/orders/'+o.id+'/cash-confirm',{method:'POST',body:{}});await refresh()},t('saved'))}
 async function flipListing(item){await run(async()=>{await api('/listings/'+item.id,{method:'PATCH',body:{...item,active:!item.active}});await refresh()},t('saved'))}
 return <DashboardShell role="seller" active={tab} onNavigate={setTab}>
  {user?.proUntil&&Date.parse(user.proUntil)>Date.now()&&<span className="shods-pro-notice"><Award size={16}/>SHODS PRO · {readable(user.proUntil,lang)}</span>}<Heading eyebrow={t('goSeller')} title={tab==='listings'?t('myItems'):tab==='incoming'?t('incoming'):t('sellerCab')} action={<button className="button primary" onClick={()=>go('add')}><Plus size={17}/>{t('addListing')}</button>}/>
  {tab==='overview'&&<div className="stats-grid"><div className="stat-card"><span><Package/></span><small>{t('myItems')}</small><strong>{mine.length}</strong></div><div className="stat-card"><span><ClipboardList/></span><small>{t('incoming')}</small><strong>{sellers.length}</strong></div><div className="stat-card"><span><CheckCircle2/></span><small>{t('completeOrder')}</small><strong>{completed.length}</strong></div></div>}
  {(tab==='overview'||tab==='listings')&&<section className="surface spaced"><div className="panel-header"><h3>{t('myItems')}</h3><button className="button outline small" onClick={()=>go('add')}><Plus size={16}/>{t('addListing')}</button></div>{mine.length?mine.map(item=><div className="listing-row" key={item.id}><div className="list-mini"><ImageFrame item={item}/></div><div className="list-info"><b>{translatedTitle(lang,item)}</b><small>{money(item.price,lang)} • {item.stock} {t('qty')}</small><span className={'status '+(item.active&&item.moderation!=='hidden'?'status-completed':'status-cancelled')}>{item.moderation==='hidden'?t('invisible'):item.active?t('active'):t('inactive')}</span></div><button className="button outline small" onClick={()=>go('add',item.id)}><Edit3 size={15}/>{t('edit')}</button><button disabled={item.moderation==='hidden'} className="button light small" onClick={()=>flipListing(item)}><Power size={15}/>{item.active?t('inactive'):t('active')}</button></div>):<div className="empty-slim">{t('noItems')}</div>}</section>}
  {(tab==='overview'||tab==='incoming')&&<section className="surface spaced"><div className="panel-header"><h3>{t('incoming')}</h3></div>{sellers.length?sellers.map(o=><div className="order-row shods-v4-order" key={o.id}>
   <div className="row-icon"><ShoppingBag/></div><div className="order-info"><b>{o.name}</b><small>{t('buyerCode')}: {o.buyerCode} • {readable(o.createdAt,lang)}</small><small>{t('qty')}: {o.qty} • {money(o.total,lang)}</small>{o.payment==='pay_on_receipt'&&<div className="v4-order-note"><Wallet size={14}/>{o.paymentStatus==='paid'?delivery(lang,'paid'):delivery(lang,'unpaid')}</div>}</div>
   <div className="order-cta"><span className={'status status-'+o.status}>{orderStatus(o,t,lang)}</span>
    {o.status==='new'&&<button className="button outline small" onClick={()=>status(o,'accepted')}>{t('accept')}</button>}
    {o.status==='accepted'&&<button className="button primary small" onClick={()=>status(o,o.payment==='pay_on_receipt'?'handed_over':'completed')}>{o.payment==='pay_on_receipt'?delivery(lang,'handoverBtn'):t('complete')}</button>}
    {o.payment==='pay_on_receipt'&&o.status==='received'&&o.paymentStatus==='unpaid'&&<button className="button primary small" onClick={()=>settleCash(o)}><CheckCircle2 size={16}/>{delivery(lang,'cashConfirm')}</button>}

    {['new','accepted'].includes(o.status)&&<button className="text-button warn" onClick={()=>status(o,'cancelled')}>{t('reject')}</button>}
   </div>
  </div>):<div className="empty-slim">{t('noOrders')}</div>}</section>}
 </DashboardShell>
}
const defaultListing={name:'',description:'',kind:'Moddiy',category:'Ta’lim',price:25000,oldPrice:'',stock:1,location:'Termiz shahri, institut hududi',active:true,image:null,imageHash:null,latitude:null,longitude:null};
function ListingEditor(){const {t,go,selectedId,mine,refresh,run,lang}=useShop();const existing=mine.find(x=>x.id===selectedId);const [form,setForm]=useState(()=>existing?{...defaultListing,...existing}:{...defaultListing});const [busy,setBusy]=useState(false);const [aiBusy,setAiBusy]=useState(false);const [photoMessage,setPhotoMessage]=useState('');const set=(k,v)=>setForm(f=>({...f,[k]:v}));
 useEffect(()=>{setForm(existing?{...defaultListing,...existing}:{...defaultListing})},[selectedId]);
 async function upload(e){
  const file=e.target.files?.[0];if(!file)return;
  setBusy(true);setPhotoMessage('Rasm tayyorlanmoqda…');
  try{
   // Show the preview immediately; only send the image when the listing is saved.
   const processed=await imageData(file);
   setForm(old=>({...old,image:processed.image,imageHash:processed.imageHash}));
   setPhotoMessage('✓ Rasm tayyor. Mahsulotni saqlash tugmasini bosing.');
  }catch(err){setPhotoMessage('Rasm xatosi: '+err.message);}
  finally{setBusy(false);e.target.value='';}
 }
 function locate(){if(!navigator.geolocation)return alert('Geolocation unavailable');navigator.geolocation.getCurrentPosition(({coords})=>setForm(f=>({...f,latitude:coords.latitude,longitude:coords.longitude})),err=>alert(err.message),{enableHighAccuracy:false,timeout:9000})}
 async function suggestDesc(){if(!form.name)return;setAiBusy(true);try{const r=await api('/ai/assist',{method:'POST',body:{action:'description',title:form.name,category:form.category,lang}});set('description',r.description)}catch(e){alert(e.message)}finally{setAiBusy(false)}}
 async function save(e){
  e.preventDefault();if(busy)return;setBusy(true);setPhotoMessage('Mahsulot saqlanmoqda…');
  try{
   const image=await resolveProductPhoto(form.image);
   const {portfolio:ignored, ...values}=form;
   const payload={...values,image,price:Number(form.price),stock:Number(form.stock)};
   await api(existing?'/listings/'+existing.id:'/listings',{method:existing?'PATCH':'POST',body:payload});
   setPhotoMessage('✓ Mahsulot saqlandi.');
   await refresh();go('seller');
  }catch(err){setPhotoMessage('Saqlash xatosi: '+err.message);alert('Mahsulot saqlanmadi: '+err.message);}
  finally{setBusy(false);}
 }
 return <div className="shell page-space"><button className="back-btn" onClick={()=>go('seller')}><ArrowLeft size={16}/>{t('goSeller')}</button><Heading title={existing?t('editListing'):t('addListing')} detail={t('sellProducts')}/><form onSubmit={save} className="listing-editor"><div className="surface"><div className="panel-header"><h3><Package size={20}/>{t('newListing')}</h3></div><div className="field-split"><label className="field"><span>{t('kind')}</span><select value={form.kind} onChange={e=>set('kind',e.target.value)}>{['Moddiy','Raqamli','Xizmat'].map(s=><option key={s} value={s}>{s==='Xizmat'?t('service'):s==='Raqamli'?t('digital'):t('physical')}</option>)}</select></label><label className="field"><span>{t('category')}</span><select value={form.category} onChange={e=>set('category',e.target.value)}>{categories.map(c=><option key={c} value={c}>{translatedCategory(lang,c)}</option>)}</select></label></div><label className="field"><span>{t('title')} *</span><input required maxLength={120} value={form.name} onChange={e=>set('name',e.target.value)} placeholder={t('title')}/></label><label className="field"><span className="label-actions">{t('description')} <button type="button" disabled={aiBusy} className="small-ai" onClick={suggestDesc}><Sparkles size={14}/>{t('aiDescription')}</button></span><textarea maxLength={1400} rows={5} value={form.description} onChange={e=>set('description',e.target.value)}/></label><div className="field-split"><label className="field"><span>{t('price')} ({t('priceUnit')})</span><input type="number" min={1} max={1000000000} required value={form.price} onChange={e=>set('price',e.target.value)}/></label><label className="field"><span>{t('stock')}</span><input type="number" min={1} max={100000} required value={form.stock} onChange={e=>set('stock',e.target.value)}/></label></div><label className="field"><span>{t('discount')}</span><input type="number" min={0} max={1000000000} value={form.oldPrice??''} onChange={e=>set('oldPrice',e.target.value)}/></label><label className="field"><span>{t('address')} *</span><input maxLength={200} required value={form.location} onChange={e=>set('location',e.target.value)} placeholder={t('locationHint')}/></label><button type="button" className="button light small" onClick={locate}><Navigation size={14}/>{t('shareLocation')}</button>{form.latitude!=null&&<div className="gps-note">GPS: {form.latitude.toFixed(5)}, {form.longitude.toFixed(5)} <button type="button" onClick={()=>setForm(f=>({...f,latitude:null,longitude:null}))}><X size={14}/></button></div>}<p className="fine-print"><AlertCircle size={14}/>{t('locationAlert')}</p><label className="toggle-line"><input type="checkbox" checked={!!form.active} onChange={e=>set('active',e.target.checked)}/><span>{t('active')} / {t('inactive')}</span><span className={'status '+(form.active?'status-completed':'status-cancelled')}>{form.active?t('active'):t('inactive')}</span></label></div>
 <div className="surface"><h3><ImagePlus size={20}/>{t('uploadPhotos')}</h3>
 <div className="upload-area" style={{gap:12}}><UploadCloud size={30}/><b>{t('photo')}</b>
 <input aria-label="Mahsulot rasmini tanlash" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" onChange={upload} disabled={busy} style={{position:'static',opacity:1,display:'block',width:'100%',maxWidth:300,height:'auto',cursor:'pointer',fontSize:12}}/>
 <small>JPG, PNG, WebP · Bir dona rasm · Avtomatik siqiladi</small></div>
 {form.image&&<div className="image-preview"><img alt="Mahsulot rasmi" src={mediaSrc(form.image)}/><button className="icon-btn" type="button" disabled={busy} onClick={()=>{setForm(f=>({...f,image:null,imageHash:null}));setPhotoMessage('Rasm olib tashlandi.')}}><X size={18}/></button></div>}
 {photoMessage&&<p role="status" style={{fontSize:12,margin:'8px 0',color:photoMessage.includes('xatosi')?'#bb3244':'var(--text)'}}>{photoMessage}</p>}
 <button className="button primary full spaced large" disabled={busy} type="submit"><CheckCircle2 size={17}/>{busy?'Saqlanmoqda…':existing?t('save'):t('create')}</button></div></form></div>}
function AIPage(){const {t,lang,go,run,user,config}=useShop();const [tab,setTab]=useState('finder'),[query,setQuery]=useState(''),[category,setCategory]=useState(categories[0]),[kind,setKind]=useState('Xizmat'),[title,setTitle]=useState(''),[scan,setScan]=useState(null),[result,setResult]=useState(null),[busy,setBusy]=useState(false);const tabs=[['finder',Search,'aiFinder'],['image',Camera,'aiImage'],['price',BarChart3,'aiPrice'],['description',FileText,'aiDescription']];async function imageUpload(e){try{const file=e.target.files?.[0];if(file){const data=await imageData(file);setScan(data);setResult(null)}}catch(e){alert(e.message)}}async function submit(e){e.preventDefault();if(!user)return go('auth');setBusy(true);try{let args={action:tab,lang};if(tab==='finder')args.query=query;else if(tab==='image')args={...args,...scan};else if(tab==='price')args={...args,kind,category};else args={...args,title,category};const res=await api('/ai/assist',{method:'POST',body:args});setResult(res)}catch(e){alert(cleanError(e,t))}finally{setBusy(false)}}
 return <div className="shell page-space"><div className="ai-header"><div className="sparkle-circle"><Sparkles size={30}/></div><div><span className="eyebrow-label">SHODS AI</span><h1>{t('aiTitle')}</h1><p>{t('aiSubtitle')}</p></div><span className="ai-badge"><span className="online-dot"/>{config.aiEnabled?t('aiModelOn'):t('aiModelOff')}</span></div><div className="ai-tabs">{tabs.map(([k,Icon,label])=><button key={k} className={tab===k?'active':''} onClick={()=>{setTab(k);setResult(null)}}><Icon size={19}/>{t(label)}</button>)}</div><div className="ai-main"><form onSubmit={submit} className="surface ai-form"><h2>{t(tabs.find(a=>a[0]===tab)[2])}</h2>{tab==='finder'&&<><p>{t('provider')}</p><label className="field"><span>{t('search')}</span><textarea value={query} required placeholder={t('aiQuery')} onChange={e=>setQuery(e.target.value)}/></label></>}{tab==='image'&&<><p>{t('aiHint')}</p><label className="upload-area"><Camera size={30}/><b>{t('photoScan')}</b><input accept="image/png,image/jpeg,image/webp" type="file" onChange={imageUpload}/></label>{scan?.image&&<img className="scan-photo" src={mediaSrc(scan.image)} alt="Scan"/>}</>}{tab==='price'&&<><label className="field"><span>{t('kind')}</span><select value={kind} onChange={e=>setKind(e.target.value)}><option value="Xizmat">{t('service')}</option><option value="Moddiy">{t('physical')}</option><option value="Raqamli">{t('digital')}</option></select></label><label className="field"><span>{t('category')}</span><select value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(c=><option key={c} value={c}>{translatedCategory(lang,c)}</option>)}</select></label></>}{tab==='description'&&<><label className="field"><span>{t('title')}</span><input value={title} required onChange={e=>setTitle(e.target.value)}/></label><label className="field"><span>{t('category')}</span><select value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(c=><option key={c} value={c}>{translatedCategory(lang,c)}</option>)}</select></label></>}<button disabled={busy||(tab==='image'&&!scan)} className="button primary full large"><Sparkles size={18}/>{busy?t('loading'):tab==='image'?t('scan'):tab==='finder'?t('find'):tab==='price'?t('suggest'):t('generate')}</button><p className="fine-print"><ShieldCheck size={14}/>{t('aiCaution')}</p></form><div className="surface ai-result"><h3><Sparkles size={20}/>{t('aiSearchResults')}</h3>{!result?<div className="ai-placeholder"><div>✦</div><p>{t('aiSubtitle')}</p></div>:<div className="ai-content"><span className="small-muted">{t('aiSource')}: {result.engine}</span>{tab==='finder'&&(result.results?.length?<div className="ai-match-list">{result.results.map(p=><button key={p.id} onClick={()=>go('detail',p.id)}><span>{p.emoji||'📦'}</span><div><b>{translatedTitle(lang,p)}</b><small>{p.sellerName} • {money(p.price,lang)}</small></div><ArrowRight size={16}/></button>)}</div>:<p>{t('noComparison')}</p>)}{tab==='image'&&<><p className="small-muted">{result.description||result.warning}</p>{(result.matches||result.visualMatches||[]).length?<div className="ai-match-list">{(result.matches?.length?result.matches:result.visualMatches).map(p=><button key={p.id} onClick={()=>go('detail',p.id)}><span>{p.emoji||'📦'}</span><div><b>{translatedTitle(lang,p)}</b><small>{money(p.price,lang)} {p.similarity?`• ${p.similarity}%`:''}</small></div><ArrowRight size={16}/></button>)}</div>:<p>{t('aiNothing')}</p>}{result.category&&<p>{t('category')}: <b>{result.category}</b></p>}</>}{tab==='price'&&(result.median?<><p>{t('median')}: <strong>{money(result.median,lang)}</strong></p><h2>{result.range.map(v=>money(v,lang)).join(' – ')}</h2><p className="small-muted">{result.note}</p></>:<p>{t('noComparison')}</p>)}{tab==='description'&&<><div className="ai-generated">{result.description}</div><button className="button outline small" onClick={()=>navigator.clipboard?.writeText(result.description)}><Copy size={15}/>{t('copied')}</button></>}</div>}</div></div></div>}
function SupportPage(){const {t,user,go,tickets,refresh,run,lang}=useShop();const [topic,setTopic]=useState('Account'),[message,setMessage]=useState('');async function send(e){e.preventDefault();if(!user)return go('auth');await run(async()=>{await api('/support',{method:'POST',body:{topic,message}});setMessage('');await refresh()},t('requestSaved'))}const faqs=[['faq1','faqA1'],['faq2','faqA2'],['faq3','faqA3']];return <div className="shell page-space"><Heading eyebrow="SHODS HELP" title={t('supportTitle')} detail={t('supportHint')}/><div className="support-grid"><div className="surface"><h3><LifeBuoy size={20}/>{t('faq')}</h3><div className="faq-list">{faqs.map(([q,a])=><details key={q}><summary>{t(q)}</summary><p>{t(a)}</p></details>)}</div><h3 className="spaced">{t('myTickets')}</h3>{user&&tickets.length?tickets.map(x=><div className="ticket" key={x.id}><b>{x.topic}</b><span className={'status status-'+(x.status==='closed'?'completed':'new')}>{x.status}</span><p>{x.message}</p><small>{readable(x.createdAt,lang)}</small>{x.reply&&<div className="ticket-reply"><b>{t('replyFromAdmin')}</b><p>{x.reply}</p></div>}</div>):<p className="small-muted">{t('empty')}</p>}</div><form className="surface" onSubmit={send}><h3><MessageCircle size={20}/>{t('newSupport')}</h3><label className="field"><span>{t('topic')}</span><select value={topic} onChange={e=>setTopic(e.target.value)}>{[['Account','problemAccount'],['Order','problemOrder'],['Listing','problemListing'],['Complaint','problemComplaint'],['Technical','problemTech']].map(([v,l])=><option key={v} value={v}>{t(l)}</option>)}</select></label><label className="field"><span>{t('message')}</span><textarea minLength={10} maxLength={1500} required rows={8} value={message} onChange={e=>setMessage(e.target.value)}/></label><button className="button primary full" type="submit"><Send size={16}/>{t('send')}</button><p className="small-muted">{t('supportHint')}</p></form></div></div>}
function AdminPage(){const {t,user,run,lang,toast,refresh}=useShop();const [tab,setTab]=useState('overview'),[data,setData]=useState({}),[loading,setLoading]=useState(false),[reply,setReply]=useState({});const tabs=[['overview',LayoutDashboard,'overview'],['users',Users,'users'],['listings',Package,'moderation'],['orders',ClipboardList,'adminOrders'],['tickets',MessageCircle,'tickets'],['reviews',Star,'adminReviews'],['ads',Sparkles,'ads'],['finance',Wallet,'financeTitle'],['news',Newspaper,'newsManage'],['audit',History,'audit']];async function load(name){setLoading(true);try{const endpoint={overview:'overview',users:'users',listings:'listings',orders:'orders',tickets:'tickets',reviews:'reviews',ads:'ads',finance:'finance',news:'news',audit:'audit'}[name];const result=await api('/admin/'+endpoint);setData(prev=>({...prev,[name]:result}))}catch(e){toast(cleanError(e,t))}finally{setLoading(false)}}useEffect(()=>{if(user?.role==='admin')load(tab)},[tab,user?.role]);if(user?.role!=='admin')return <div className="shell page-space"><div className="empty-state"><LockKeyhole size={33}/><h3>{t('accessDenied')}</h3></div></div>;
 const change=async(url,payload,method='PATCH')=>run(async()=>{await api(url,{method,body:payload});await load(tab);await refresh()},t('adminSuccess'));
 async function exportData(){try{const r=await api('/admin/export');const blob=new Blob([JSON.stringify(r,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`SHODS_ADMIN_REPORT_${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url)}catch(e){toast(cleanError(e,t))}}
 const rows=data[tab]||{};
 return <div className="shell page-space admin-page"><div className="admin-hero"><div className="admin-symbol"><ShieldCheck size={27}/></div><div><span className="eyebrow-label">SHODS SHOP</span><h1>{t('admin')}</h1><p>{t('adminSecure')}</p></div><button className="button outline" onClick={exportData}><Download size={16}/>{t('backup')}</button></div><div className="admin-layout"><aside className="surface admin-menu"><span className="sidebar-caption">{t('admin')}</span>{tabs.map(([key,Icon,label])=><button key={key} className={tab===key?'current':''} onClick={()=>setTab(key)}><Icon size={18}/>{t(label)}</button>)}</aside><div className="admin-content"><div className="panel-header"><h2>{t(tabs.find(x=>x[0]===tab)?.[2]||tab)}</h2><button className="button outline small" onClick={()=>load(tab)}><RefreshCcw size={15}/>{t('reload')}</button></div>{loading&&<div className="loading-line"/>}
 {tab==='overview'&&<><div className="stats-grid admin-stats">{[['users',Users,'usersCount'],['listings',Package,'listingsCount'],['orders',ClipboardList,'ordersCount'],['demoTurnover',Wallet,'demoSum'],['newsPublished',Newspaper,'news'],['ticketsOpen',MessageCircle,'openTickets'],['reviews',Star,'adminReviews']].map(([id,Icon,label])=><div className="stat-card" key={id}><span><Icon/></span><small>{t(label)}</small><strong>{id==='demoTurnover'?money(rows.stats?.[id],lang):rows.stats?.[id]??0}</strong></div>)}</div><section className="surface spaced"><h3>{t('lastActivity')}</h3><div className="admin-table-wrap"><table><thead><tr><th>ID</th><th>{t('title')}</th><th>{t('price')}</th><th>{t('status')}</th></tr></thead><tbody>{rows.recentOrders?.map(o=><tr key={o.id}><td>{o.id.slice(0,12)}</td><td>{o.name}</td><td>{money(o.total,lang)}</td><td>{o.status}</td></tr>)}</tbody></table></div></section></>}
 {tab==='users'&&<div className="surface admin-table-wrap"><table><thead><tr><th>{t('name')}</th><th>{t('username')}</th><th>{t('institute')}</th><th>{t('accountStatus')}</th><th>{t('actions')}</th></tr></thead><tbody>{rows.users?.map(u=><tr key={u.id}><td><b>{u.name}</b>{u.role==='admin'&&<span className="role-chip">ADMIN</span>}</td><td>{u.login}</td><td>{u.institute}</td><td><span className={'status '+(u.status==='suspended'?'status-cancelled':'status-completed')}>{u.status}</span></td><td>{u.role!=='admin'?<button className={'button small '+(u.status==='suspended'?'outline':'light')} onClick={()=>change('/admin/users/'+u.id,{status:u.status==='suspended'?'active':'suspended'})}>{u.status==='suspended'?t('unblock'):t('block')}</button>:'—'}</td></tr>)}</tbody></table></div>}
 {tab==='listings'&&<div className="surface admin-table-wrap"><table><thead><tr><th>{t('title')}</th><th>{t('seller')}</th><th>{t('price')}</th><th>{t('status')}</th><th>{t('actions')}</th></tr></thead><tbody>{rows.items?.map(p=><tr key={p.id}><td><b>{translatedTitle(lang,p)}</b><small>{translatedCategory(lang,p.category)}</small></td><td>{p.sellerName}</td><td>{money(p.price,lang)}</td><td><span className={'status '+(p.moderation==='hidden'?'status-cancelled':'status-completed')}>{p.moderation==='hidden'?t('invisible'):t('visible')}</span></td><td><button className="button light small" onClick={()=>change('/admin/listings/'+p.id,{moderation:p.moderation==='hidden'?'approved':'hidden'})}>{p.moderation==='hidden'?t('restore'):t('hide')}</button></td></tr>)}</tbody></table></div>}
 {tab==='orders'&&<div className="surface admin-table-wrap"><table><thead><tr><th>{t('title')}</th><th>{t('buyer')}</th><th>{t('seller')}</th><th>{t('sum')}</th><th>{t('status')}</th></tr></thead><tbody>{rows.orders?.map(o=><tr key={o.id}><td><b>{o.name}</b><small>#{o.id.slice(0,14)}</small></td><td>{o.buyerName}</td><td>{o.sellerName}</td><td>{money(o.total,lang)}</td><td>{o.status}</td></tr>)}</tbody></table></div>}
 {tab==='tickets'&&<div className="admin-tickets">{rows.tickets?.length?rows.tickets.map(ticket=><div className="surface" key={ticket.id}><div className="panel-header"><h3>{ticket.topic}</h3><span className={'status '+(ticket.status==='closed'?'status-completed':'status-new')}>{ticket.status}</span></div><small>{ticket.userName} • {readable(ticket.createdAt,lang)}</small><p>{ticket.message}</p><label className="field"><span>{t('answer')}</span><textarea rows={3} value={reply[ticket.id]??ticket.reply??''} onChange={e=>setReply(s=>({...s,[ticket.id]:e.target.value}))}/></label><div className="admin-buttons"><button className="button primary small" onClick={()=>change('/admin/tickets/'+ticket.id,{status:'answered',reply:reply[ticket.id]??ticket.reply??''})}>{t('sendAnswer')}</button><button className="button light small" onClick={()=>change('/admin/tickets/'+ticket.id,{status:'closed',reply:reply[ticket.id]??ticket.reply??''})}>{t('closeTicket')}</button></div></div>):<div className="empty-slim">{t('empty')}</div>}</div>}
 {tab==='reviews'&&<div className="surface admin-table-wrap"><table><thead><tr><th>{t('buyer')}</th><th>{t('title')}</th><th>{t('stars')}</th><th>{t('reviewText')}</th><th>{t('actions')}</th></tr></thead><tbody>{rows.reviews?.map(r=><tr key={r.id}><td>{r.buyerName}</td><td>{r.itemId}</td><td>{'★'.repeat(r.stars)}</td><td>{r.text}</td><td><button className="button light small" onClick={()=>{if(window.confirm(t('removeReview')+'?'))change('/admin/reviews/'+r.id,undefined,'DELETE')}}><Trash2 size={14}/>{t('removeReview')}</button></td></tr>)}</tbody></table></div>}
 {tab==='ads'&&<AdminAdsTab/>}{tab==='finance'&&<AdminFinanceTab onUpdated={()=>load('finance')}/>} {tab==='news'&&<AdminNewsTab/>}
 {tab==='audit'&&<div className="surface admin-table-wrap"><table><thead><tr><th>{t('createdAt')}</th><th>{t('admin')}</th><th>{t('actions')}</th><th>{t('title')}</th></tr></thead><tbody>{rows.audit?.map(r=><tr key={r.id}><td>{readable(r.at,lang)}</td><td>{r.adminName}</td><td>{r.action}</td><td>{r.target}</td></tr>)}</tbody></table></div>}
 </div></div></div>}
function AdminFinanceTab({onUpdated}){
 const {t,lang,toast}=useShop();
 const [report,setReport]=useState({entries:[],totalReceived:0,proSellers:[],boostedListings:[]});
 const [loading,setLoading]=useState(false),[entry,setEntry]=useState({kind:'advertisement',amount:100000,description:''});
 const [boostId,setBoostId]=useState(''),[proId,setProId]=useState('');
 const [users,setUsers]=useState([]),[listings,setListings]=useState([]);
 async function load(){setLoading(true);try{const [a,b,c]=await Promise.all([api('/admin/finance'),api('/admin/users'),api('/admin/listings')]);setReport(a);setUsers(b.users||[]);setListings(c.items||[])}catch(e){toast(e.message)}finally{setLoading(false)}}
 useEffect(()=>{load()},[]);
 async function addIncome(e){e.preventDefault();if(!window.confirm(lang==='ru'?'Вы действительно получили эти наличные?':lang==='en'?'Have you actually received this cash?':'Bu naqd pul haqiqatan qo‘lingizga tushganmi?'))return;setLoading(true);try{await api('/admin/finance',{method:'POST',body:{...entry,amount:Number(entry.amount)}});setEntry({kind:'advertisement',amount:100000,description:''});await load();onUpdated?.();toast('Naqd tushum qayd etildi')}catch(e){toast(e.message)}finally{setLoading(false)}}
 async function changeBenefit(type,id,days){if(!id)return;setLoading(true);try{await api(`/admin/${type}/${encodeURIComponent(id)}`,{method:'PATCH',body:{days}});await load();onUpdated?.();toast('Bajarildi')}catch(e){toast(e.message)}finally{setLoading(false)}}
 return <div className="shods-finance"><section className="surface shods-finance-head"><div><span className="eyebrow-label">SHODS BUSINESS</span><h3>{lang==='ru'?'Монетизация':lang==='en'?'Monetization':'Daromad boshqaruvi'}</h3><p>Faqat admin qayd etgan, haqiqatda olingan naqd tushum. Savdo aylanmasi platforma daromadi emas.</p></div><strong>{money(report.totalReceived,lang)}</strong></section>
 <div className="shods-finance-grid"><form className="surface form-stack" onSubmit={addIncome}><h3>Naqd tushumni qayd etish</h3><label className="field"><span>Daromad turi</span><select value={entry.kind} onChange={e=>setEntry({...entry,kind:e.target.value})}><option value="advertisement">Reklama</option><option value="top">TOP e’lon</option><option value="pro">SHODS PRO</option><option value="other">Boshqa xizmat</option></select></label><label className="field"><span>Haqiqatan qabul qilingan summa (so‘m)</span><input type="number" required min="1" max="100000000" value={entry.amount} onChange={e=>setEntry({...entry,amount:e.target.value})}/></label><label className="field"><span>Izoh / to‘lov maqsadi</span><input required minLength="3" maxLength="200" placeholder="Masalan: 7 kunlik reklama" value={entry.description} onChange={e=>setEntry({...entry,description:e.target.value})}/></label><button className="button primary full" disabled={loading}><Wallet size={17}/>Tushumni saqlash</button></form>
 <section className="surface form-stack"><h3>TOP e’lon va PRO</h3><p className="small-muted">Pullik imkoniyatlarni faqat kelishuv va to‘lovni tekshirgandan keyin faollashtiring. Faollashtirishning o‘zi daromad yaratmaydi.</p><label className="field"><span>Mahsulotni TOP qilish</span><select value={boostId} onChange={e=>setBoostId(e.target.value)}><option value="">Mahsulotni tanlang</option>{listings.map(x=><option key={x.id} value={x.id}>{x.name} — {x.sellerName}</option>)}</select></label><div className="shods-finance-actions"><button type="button" className="button primary small" disabled={!boostId||loading} onClick={()=>changeBenefit('boost',boostId,7)}>TOP · 7 kun</button><button type="button" className="button light small" disabled={!boostId||loading} onClick={()=>changeBenefit('boost',boostId,0)}>TOPni o‘chirish</button></div><label className="field"><span>SHODS PRO sotuvchi</span><select value={proId} onChange={e=>setProId(e.target.value)}><option value="">Foydalanuvchini tanlang</option>{users.filter(u=>u.role!=='admin').map(u=><option key={u.id} value={u.id}>{u.name} ({u.login})</option>)}</select></label><div className="shods-finance-actions"><button type="button" className="button primary small" disabled={!proId||loading} onClick={()=>changeBenefit('pro',proId,30)}>PRO · 30 kun</button><button type="button" className="button light small" disabled={!proId||loading} onClick={()=>changeBenefit('pro',proId,0)}>PROni o‘chirish</button></div></section></div>
 <section className="surface"><div className="panel-header"><h3>Naqd tushumlar tarixi</h3><button className="button outline small" onClick={load}><RefreshCcw size={15}/>Yangilash</button></div>{report.entries?.length?<div className="shods-finance-history">{report.entries.map(row=><div key={row.id}><span><b>{({advertisement:'Reklama',top:'TOP e’lon',pro:'SHODS PRO',other:'Boshqa'})[row.kind]}</b><small>{row.description} · {readable(row.confirmedAt,lang)}</small></span><strong>{money(row.amount,lang)}</strong></div>)}</div>:<p className="small-muted">Hozircha tushum qayd etilmagan.</p>}</section></div>
}

// SHODS SHOP 3.1 — ads become part of the branded home hero.
// All slides still come from the existing admin-managed /api/ads endpoint.
function AdsCarousel(){
 const {t,go,lang}=useShop();
 const [ads,setAds]=useState([]);
 const [index,setIndex]=useState(0);
 const [paused,setPaused]=useState(false);
 const [hovered,setHovered]=useState(false);
 const [brokenImageId,setBrokenImageId]=useState(null);
 useEffect(()=>{
  let alive=true;
  api('/ads').then(r=>{if(alive)setAds(Array.isArray(r.ads)?r.ads:[])}).catch(()=>{});
  return()=>{alive=false};
 },[]);
 const fallback=[
  {id:'intro1',theme:'blue',title:t('promo1'),subtitle:t('promoDesc1'),target:'add',emoji:'🎓'},
  {id:'intro2',theme:'teal',title:t('promo2'),subtitle:t('promoDesc2'),target:'services',emoji:'📚'},
  {id:'intro3',theme:'violet',title:t('promo3'),subtitle:t('promoDesc3'),target:'ai',emoji:'✨'}
 ];
 const slides=ads.length?ads:fallback;
 const activeIndex=index%slides.length;
 const active=slides[activeIndex];
 const visibleImage=Boolean(active.image) && brokenImageId!==active.id;
 const theme=['blue','teal','orange','violet'].includes(active.theme)?active.theme:'blue';
 useEffect(()=>{
  if(paused||hovered||slides.length<2||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;
  const interval=setInterval(()=>setIndex(i=>(i+1)%slides.length),5600);
  return()=>clearInterval(interval);
 },[paused,hovered,slides.length]);
 const previous=()=>setIndex(i=>(i+slides.length-1)%slides.length);
 const next=()=>setIndex(i=>(i+1)%slides.length);
 const prevTitle=lang==='ru'?'Предыдущая реклама':lang==='en'?'Previous advertisement':'Oldingi reklama';
 const nextTitle=lang==='ru'?'Следующая реклама':lang==='en'?'Next advertisement':'Keyingi reklama';
 return <div className="shods-hero-ads" role="region" aria-label={t('ads')}
  onMouseEnter={()=>setHovered(true)} onMouseLeave={()=>setHovered(false)}
  onFocusCapture={()=>setHovered(true)} onBlurCapture={e=>{if(!e.currentTarget.contains(e.relatedTarget))setHovered(false)}}>
  <article className={'shods-ad-card shods-ad-'+theme} key={active.id}>
   <div className="shods-ad-head"><span className="shods-ad-kicker"><Sparkles size={15}/> SHODS SHOP <span className="shods-ad-head-dot">•</span> {t('promo')}</span>
    <span className="shods-ad-edition"><GraduationCap size={15}/> TALABALAR BOZORI</span></div>
   <div className="shods-ad-main">
    <div className="shods-ad-copy">
     <span className="shods-ad-topline">SHODS SHOP · 2026</span>
     <h2>{active.title}</h2>
     {active.subtitle&&<p>{active.subtitle}</p>}
     <button type="button" className="shods-ad-cta" onClick={()=>go(active.target||'catalog')}>{t('adAction')} <ArrowRight size={17}/></button>
    </div>
    <div className="shods-ad-product"><div className="shods-ad-product-frame">
     {visibleImage?<img src={mediaSrc(active.image)} alt={active.title||t('ads')} loading="eager" onError={()=>setBrokenImageId(active.id)}/>:<span role="img" aria-label={active.title}>{active.emoji||'🛍️'}</span>}
    </div><div className="shods-ad-product-caption"><ShoppingBag size={14}/> SHODS SHOP</div></div>
   </div>
   <div className="shods-ad-bottom">
    <span className="shods-ad-counter">{String(activeIndex+1).padStart(2,'0')} <span>/</span> {String(slides.length).padStart(2,'0')}</span>
    <div className="shods-ad-navigation">
     <button type="button" className="shods-ad-arrow" aria-label={prevTitle} onClick={previous}>‹</button>
     <div className="shods-ad-dots">{slides.map((slide,i)=><button type="button" key={slide.id||i} className={i===activeIndex?'active':''} aria-label={'Slide '+(i+1)} aria-current={i===activeIndex?'true':undefined} onClick={()=>setIndex(i)}/>)}</div>
     <button type="button" className="shods-ad-arrow" aria-label={nextTitle} onClick={next}>›</button>
     <button type="button" className="shods-ad-pause" aria-label={paused?t('adPlay'):t('adPause')} onClick={()=>setPaused(p=>!p)}>{paused?'▶':'Ⅱ'}</button>
    </div>
   </div>
  </article>
 </div>;
}

function ChatsPage(){
 const {t,lang,user,go,selectedId,toast}=useShop();const [chats,setChats]=useState([]),[active,setActive]=useState(selectedId||null),[messages,setMessages]=useState([]),[draft,setDraft]=useState(''),[busy,setBusy]=useState(false);
 const bottom=useRef(null);
 async function reload(){try{const r=await api('/chats');setChats(r.chats||[]);setActive(v=>v||selectedId||r.chats?.[0]?.id||null)}catch(e){toast(e.message)}}
 useEffect(()=>{if(user){reload();const timer=setInterval(reload,15000);return()=>clearInterval(timer)}},[user?.id]);
 useEffect(()=>{if(selectedId)setActive(selectedId)},[selectedId]);
 useEffect(()=>{if(!active)return;let live=true;const read=async()=>{try{const r=await api('/chats/'+encodeURIComponent(active)+'/messages');if(live)setMessages(r.messages||[])}catch(e){if(live)toast(e.message)}};read();const timer=setInterval(read,7000);return()=>{live=false;clearInterval(timer)}},[active]);
 useEffect(()=>{bottom.current?.scrollIntoView({behavior:'smooth',block:'end'})},[messages.length]);
 async function send(e){e.preventDefault();const text=draft.trim();if(!text||!active||busy)return;setBusy(true);try{await api('/chats/'+active+'/messages',{method:'POST',body:{text}});setDraft('');const r=await api('/chats/'+active+'/messages');setMessages(r.messages);await reload()}catch(e){toast(e.message)}finally{setBusy(false)}}
 if(!user)return <div className="shell page-space"><div className="empty-state"><LockKeyhole/><h3>{t('loginRequired')}</h3><button className="button primary" onClick={()=>go('auth')}>{t('login')}</button></div></div>;
 const chat=chats.find(c=>c.id===active);
 return <div className="shell page-space"><Heading eyebrow="SHODS CONNECT" title={t('chatTitle')} detail={t('chatInfo')}/><div className="v3-chat-layout"><aside className="surface v3-chats-sidebar"><h3><MessageCircle size={18}/>{t('chat')}</h3>{chats.length?chats.map(c=><button key={c.id} className={'v3-chat-preview '+(c.id===active?'selected':'')} onClick={()=>setActive(c.id)}><span className="v3-avatar">{c.other?.name?.[0]||'S'}</span><span><b>{c.other?.name||'Talaba'}</b><small>{c.lastMessage?.text||t('chatPlaceholder')}</small></span></button>):<p className="small-muted">{t('chatEmpty')}</p>}</aside><div className="surface v3-chat-panel"><div className="v3-chat-heading"><div className="v3-avatar">{chat?.other?.name?.[0]||'S'}</div><div><strong>{chat?.other?.name||t('noChats')}</strong><small>{chat?.other?.institute||''}</small></div></div><div className="v3-messages">{chat?messages.map(m=><div key={m.id} className={'v3-bubble '+(m.from===user.id?'mine':'theirs')}><div>{m.text}</div><small>{readable(m.createdAt,lang)}</small></div>):<p className="small-muted">{t('chatEmpty')}</p>}<span ref={bottom}/></div><form className="v3-chat-send" onSubmit={send}><input disabled={!chat||busy} maxLength={1200} value={draft} onChange={e=>setDraft(e.target.value)} placeholder={t('chatPlaceholder')}/><button className="button primary" disabled={!chat||busy||!draft.trim()}><Send size={17}/>{t('chatSend')}</button></form></div></div></div>
}

function JobsPage(){
 const {t,lang,user,go,toast}=useShop();const [jobs,setJobs]=useState([]),[mine,setMine]=useState([]),[selected,setSelected]=useState(null),[proposals,setProposals]=useState([]),[formOpen,setFormOpen]=useState(false),[create,setCreate]=useState({title:'',description:'',category:'Slayd',budget:50000,deadline:''}),[proposal,setProposal]=useState({price:50000,note:''}),[busy,setBusy]=useState(false);
 async function load(){const r=await api('/jobs');setJobs(r.jobs||[]);if(user){const v=await api('/jobs/mine');setMine(v.jobs||[])}}
 useEffect(()=>{load().catch(e=>toast(e.message))},[user?.id]);
 async function openJob(job){setSelected(job);if(user){try{setProposals((await api('/jobs/'+job.id+'/proposals')).proposals||[])}catch(e){toast(e.message)}}}
 async function post(e){e.preventDefault();setBusy(true);try{await api('/jobs',{method:'POST',body:{...create,budget:Number(create.budget)}});setFormOpen(false);setCreate({title:'',description:'',category:'Slayd',budget:50000,deadline:''});await load();toast(t('saved'))}catch(e){toast(e.message)}finally{setBusy(false)}}
 async function apply(e){e.preventDefault();if(!user)return go('auth');setBusy(true);try{await api('/jobs/'+selected.id+'/proposals',{method:'POST',body:{...proposal,price:Number(proposal.price)}});toast(t('jobProposalSent'));await openJob(selected);await load()}catch(e){toast(e.message)}finally{setBusy(false)}}
 async function accept(id){setBusy(true);try{await api('/jobs/'+selected.id+'/accept',{method:'PATCH',body:{proposalId:id}});await load();setSelected(null);toast(t('saved'))}catch(e){toast(e.message)}finally{setBusy(false)}}
 return <div className="shell page-space"><Heading eyebrow="SHODS SERVICE HUB" title={t('jobBoard')} detail={t('jobInfo')} action={<button className="button primary" onClick={()=>user?setFormOpen(v=>!v):go('auth')}><Plus size={17}/>{t('jobNew')}</button>}/>
 {formOpen&&<form className="surface v3-job-form" onSubmit={post}><h3>{t('jobNew')}</h3><label className="field"><span>{t('jobTitle')}</span><input required minLength={5} maxLength={120} value={create.title} onChange={e=>setCreate({...create,title:e.target.value})}/></label><label className="field"><span>{t('jobDesc')}</span><textarea required minLength={15} maxLength={1500} rows={4} value={create.description} onChange={e=>setCreate({...create,description:e.target.value})}/></label><div className="field-split"><label className="field"><span>{t('category')}</span><select value={create.category} onChange={e=>setCreate({...create,category:e.target.value})}>{categories.map(c=><option key={c}>{c}</option>)}</select></label><label className="field"><span>{t('jobBudget')}</span><input required min={1000} type="number" value={create.budget} onChange={e=>setCreate({...create,budget:e.target.value})}/></label></div><label className="field"><span>{t('jobDeadline')}</span><input type="date" value={create.deadline} onChange={e=>setCreate({...create,deadline:e.target.value})}/></label><button disabled={busy} className="button primary">{t('jobNew')}</button></form>}
 <div className="v3-job-grid">{jobs.length?jobs.map(j=><article className="surface v3-job" key={j.id}><span className="eyebrow-label">{j.category} · {j.status==='assigned'?t('jobAssigned'):t('jobOpen')}</span><h3>{j.title}</h3><p>{j.description}</p><div className="v3-job-meta"><strong>{money(j.budget,lang)}</strong><small>{j.buyerName} • {j.proposalCount} {t('jobOffers')}</small></div>{j.deadline&&<small>📅 {j.deadline}</small>}<button className="button outline full" onClick={()=>user?openJob(j):go('auth')}>{t('jobOffers')} <ArrowRight size={16}/></button></article>):<div className="surface"><p>{t('noJobs')}</p></div>}</div>
 {selected&&<div className="v3-modal-backdrop" onClick={()=>setSelected(null)}><section className="surface v3-job-modal" onClick={e=>e.stopPropagation()}><div className="panel-header"><h2>{selected.title}</h2><button className="icon-btn" onClick={()=>setSelected(null)}><X/></button></div><p>{selected.description}</p><strong>{money(selected.budget,lang)}</strong><h3>{t('jobOffers')}</h3>{proposals.map(p=><div className="v3-offer" key={p.id}><div><b>{p.sellerName}</b><p>{p.note}</p><small>{money(p.price,lang)} · {p.status}</small></div>{selected.buyer===user?.id && selected.status==='open'&&<button className="button primary small" disabled={busy} onClick={()=>accept(p.id)}>{t('jobAccept')}</button>}</div>)}{selected.buyer!==user?.id&&selected.status==='open'&&<form className="v3-proposal-form" onSubmit={apply}><label className="field"><span>{t('jobOfferPrice')}</span><input type="number" min="1000" required value={proposal.price} onChange={e=>setProposal({...proposal,price:e.target.value})}/></label><label className="field"><span>{t('jobOfferText')}</span><textarea minLength={8} maxLength={700} required value={proposal.note} onChange={e=>setProposal({...proposal,note:e.target.value})}/></label><button className="button primary" disabled={busy}>{t('jobSend')}</button></form>}</section></div>}
 {user&&mine.length>0&&<section className="v3-myjobs"><Heading title={t('jobMy')}/>{mine.map(j=><div className="surface v3-myjob" key={j.id}><b>{j.title}</b><small>{j.status}</small></div>)}</section>}
 </div>
}

