function AdminAdsTab(){const {t,toast}=useShop();const [list,setList]=useState([]),[form,setForm]=useState({title:'',subtitle:'',theme:'blue',target:'catalog',image:null,active:true}),[busy,setBusy]=useState(false);const [photo,setPhoto]=useState('');async function load(){const r=await api('/admin/ads');setList(r.ads||[])}useEffect(()=>{load().catch(e=>toast(e.message))},[]);
 async function upload(e){const file=e.target.files?.[0];if(!file)return;setBusy(true);try{const img=await imageData(file);const stored=await resolveProductPhoto(img.image);setForm(x=>({...x,image:stored}));setPhoto(file.name)}catch(e){toast(e.message)}finally{setBusy(false)}}
 async function submit(e){e.preventDefault();setBusy(true);try{await api('/admin/ads',{method:'POST',body:form});setForm({title:'',subtitle:'',theme:'blue',target:'catalog',image:null,active:true});setPhoto('');await load();toast(t('saved'))}catch(e){toast(e.message)}finally{setBusy(false)}}
 async function toggle(ad){try{await api('/admin/ads/'+ad.id,{method:'PATCH',body:{active:!ad.active}});await load()}catch(e){toast(e.message)}}
 async function remove(ad){if(!window.confirm(t('adRemove')+'?'))return;try{await api('/admin/ads/'+ad.id,{method:'DELETE'});await load()}catch(e){toast(e.message)}}
 return <div className="v3-adminads"><form className="surface v3-ad-form" onSubmit={submit}><h3>{t('adNew')}</h3><label className="field"><span>{t('adTitle')}</span><input maxLength={100} required value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label className="field"><span>{t('adSubtitle')}</span><textarea maxLength={200} value={form.subtitle} onChange={e=>setForm({...form,subtitle:e.target.value})}/></label><div className="field-split"><label className="field"><span>{t('adDestination')}</span><select value={form.target} onChange={e=>setForm({...form,target:e.target.value})}>{['catalog','services','jobs','ai','home'].map(x=><option key={x} value={x}>{x}</option>)}</select></label><label className="field"><span>{t('adColor')}</span><select value={form.theme} onChange={e=>setForm({...form,theme:e.target.value})}>{['blue','teal','orange','violet'].map(x=><option key={x}>{x}</option>)}</select></label></div><label className="field"><span>{t('adPhoto')}</span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={upload}/></label>{form.image&&<img className="v3-ad-preview-img" src={mediaSrc(form.image)} alt={photo||t('adPhoto')}/>}<label className="toggle-line"><input type="checkbox" checked={form.active} onChange={e=>setForm({...form,active:e.target.checked})}/>{t('adActive')}</label><button className="button primary" disabled={busy}><Plus size={17}/>{t('adNew')}</button></form><section className="surface"><h3>{t('adManage')}</h3>{list.length?list.map(ad=><div className="v3-ad-adminrow" key={ad.id}><div><b>{ad.title}</b><small>{ad.subtitle}</small><small>{ad.active?'● Active':'○ Inactive'} · {ad.target}</small></div><div><button className="button light small" onClick={()=>toggle(ad)}>{ad.active?t('adPause'):t('adPlay')}</button><button className="button light small" onClick={()=>remove(ad)}><Trash2 size={14}/></button></div></div>):<p className="small-muted">{t('adEmpty')}</p>}</section></div>
}

// SHODS SHOP: publicly readable announcements, offers and news.
function localizedNews(entry,lang){
 const suffix=lang==='ru'?'Ru':lang==='en'?'En':'';
 return {title:entry['title'+suffix]||entry.title,body:entry['body'+suffix]||entry.body};
}
function NewsPreview(){
 const {t,go,lang}=useShop(),[items,setItems]=useState([]);
 useEffect(()=>{api('/news').then(x=>setItems(x.news||[])).catch(()=>{})},[]);
 if(!items.length)return null;
 return <section className="shell v3-news-preview"><Heading eyebrow="SHODS SHOP" title={t('news')} detail={t('newsSubtitle')} action={<button className="button outline small" onClick={()=>go('news')}>{t('viewAll')} <ArrowRight size={15}/></button>}/><div className="v3-news-grid">{items.slice(0,3).map(n=>{const copy=localizedNews(n,lang);return <article className="surface v3-news-card" key={n.id}><span className={'v3-news-type type-'+n.kind}>{t('newsType_'+n.kind)}</span>{n.image&&<img src={mediaSrc(n.image)} alt="" loading="lazy"/>}<h3>{copy.title}</h3><p>{copy.body}</p><small>{readable(n.createdAt,lang)}</small><button className="button outline small" onClick={()=>go('news',n.id)}>{t('readMore')} <ArrowRight size={14}/></button></article>})}</div></section>
}
function NewsPage(){
 const {t,lang,selectedId}=useShop(),[items,setItems]=useState([]),[kind,setKind]=useState('all');
 useEffect(()=>{api('/news').then(x=>setItems(x.news||[])).catch(()=>{})},[]);
 const visible=items.filter(n=>kind==='all'||n.kind===kind).sort((a,b)=>(a.id===selectedId?-1:b.id===selectedId?1:0));
 return <div className="shell page-space"><Heading eyebrow="SHODS SHOP" title={t('news')} detail={t('newsSubtitle')}/><div className="v3-news-filters"><button className={'button '+(kind==='all'?'primary':'outline')} onClick={()=>setKind('all')}>{t('all')}</button>{['news','offer','notice'].map(k=><button className={'button '+(kind===k?'primary':'outline')} key={k} onClick={()=>setKind(k)}>{t('newsType_'+k)}</button>)}</div><div className="v3-news-list">{visible.length?visible.map(n=>{const copy=localizedNews(n,lang);return <article key={n.id} className={'surface v3-news-story '+(n.id===selectedId?'highlighted':'')}><div><span className={'v3-news-type type-'+n.kind}>{t('newsType_'+n.kind)}</span><small>{readable(n.createdAt,lang)}</small></div><h2>{copy.title}</h2>{n.image&&<img src={mediaSrc(n.image)} alt="" loading="lazy"/>}<p>{copy.body}</p></article>}):<div className="empty-state"><Newspaper size={36}/><h3>{t('newsEmpty')}</h3></div>}</div></div>
}
// Admin-only news editor. All calls use /api/admin/ and the server enforces role checks.
function AdminNewsTab(){
 const {t,toast,lang}=useShop(),[news,setNews]=useState([]),[busy,setBusy]=useState(false),[editing,setEditing]=useState(null);
 const empty=()=>({title:'',body:'',titleRu:'',bodyRu:'',titleEn:'',bodyEn:'',kind:'news',image:null,published:true,broadcast:true});
 const [form,setForm]=useState(empty);
 async function load(){const x=await api('/admin/news');setNews(x.news||[])}
 useEffect(()=>{load().catch(e=>toast(e.message))},[]);
 const patch=(key,val)=>setForm(s=>({...s,[key]:val}));
 function edit(n){setEditing(n.id);setForm({title:n.title,body:n.body,titleRu:n.titleRu||'',bodyRu:n.bodyRu||'',titleEn:n.titleEn||'',bodyEn:n.bodyEn||'',kind:n.kind,image:n.image||null,published:n.published,broadcast:false});}
 async function imageUpload(e){const f=e.target.files?.[0];if(!f)return;setBusy(true);try{const img=await imageData(f);const url=await resolveProductPhoto(img.image);patch('image',url)}catch(e){toast(e.message)}finally{setBusy(false)}}
 async function submit(e){e.preventDefault();setBusy(true);try{await api('/admin/news'+(editing?'/'+editing:''),{method:editing?'PATCH':'POST',body:form});setEditing(null);setForm(empty());await load();toast(t('saved'))}catch(e){toast(e.message)}finally{setBusy(false)}}
 async function toggle(n){try{await api('/admin/news/'+n.id,{method:'PATCH',body:{published:!n.published,broadcast:false}});await load()}catch(e){toast(e.message)}}
 async function sendAgain(n){if(!window.confirm(t('newsBroadcastConfirm')))return;try{await api('/admin/news/'+n.id,{method:'PATCH',body:{broadcast:true}});await load();toast(t('newsSent'))}catch(e){toast(e.message)}}
 async function remove(n){if(!window.confirm(t('newsDeleteConfirm')))return;try{await api('/admin/news/'+n.id,{method:'DELETE'});await load()}catch(e){toast(e.message)}}
 return <div className="v3-admin-news"><form className="surface v3-news-admin-form" onSubmit={submit}><div className="panel-header"><h3><Newspaper size={19}/>{editing?t('newsEdit'):t('newsCreate')}</h3>{editing&&<button type="button" className="button outline small" onClick={()=>{setEditing(null);setForm(empty())}}>{t('cancel')}</button>}</div><div className="field-split"><label className="field"><span>{t('newsKind')}</span><select value={form.kind} onChange={e=>patch('kind',e.target.value)}>{['news','offer','notice'].map(x=><option value={x} key={x}>{t('newsType_'+x)}</option>)}</select></label><label className="field"><span>{t('newsCover')}</span><input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onChange={imageUpload}/></label></div>{form.image&&<img className="v3-news-cover-preview" src={mediaSrc(form.image)} alt=""/>}<label className="field"><span>{t('newsTitle')} (O‘zbekcha) *</span><input required minLength={5} maxLength={125} value={form.title} onChange={e=>patch('title',e.target.value)}/></label><label className="field"><span>{t('newsText')} (O‘zbekcha) *</span><textarea required minLength={15} maxLength={3500} rows={4} value={form.body} onChange={e=>patch('body',e.target.value)}/></label><details><summary>Русский / English</summary>{[['Ru','Русский'],['En','English']].map(([suffix,label])=><div key={suffix}><label className="field"><span>{t('newsTitle')} — {label}</span><input maxLength={125} value={form['title'+suffix]} onChange={e=>patch('title'+suffix,e.target.value)}/></label><label className="field"><span>{t('newsText')} — {label}</span><textarea maxLength={3500} rows={3} value={form['body'+suffix]} onChange={e=>patch('body'+suffix,e.target.value)}/></label></div>)}</details><label className="toggle-line"><input type="checkbox" checked={!!form.published} onChange={e=>patch('published',e.target.checked)}/>{t('newsPublished')}</label><label className="toggle-line"><input type="checkbox" checked={!!form.broadcast} disabled={!form.published} onChange={e=>patch('broadcast',e.target.checked)}/><Bell size={16}/>{t('newsNotifyAll')}</label><p className="small-muted">{t('newsNotifyInfo')}</p><button className="button primary" disabled={busy}><Send size={16}/>{editing?t('save'):t('newsPublish')}</button></form><section className="surface v3-admin-news-list"><h3>{t('newsManage')}</h3>{news.length?news.map(n=><div className="v3-news-adminrow" key={n.id}><div><span className={'v3-news-type type-'+n.kind}>{t('newsType_'+n.kind)}</span><b>{localizedNews(n,lang).title}</b><small>{n.published?t('newsPublished'):t('newsDraft')} · {readable(n.createdAt,lang)}</small></div><div className="v3-news-actions"><button className="button light small" onClick={()=>edit(n)}>{t('edit')}</button><button className="button outline small" onClick={()=>toggle(n)}>{n.published?t('newsHide'):t('newsShow')}</button>{n.published&&<button className="button light small" onClick={()=>sendAgain(n)}><Bell size={14}/>{t('newsNotifyAll')}</button>}<button className="button light small" onClick={()=>remove(n)}><Trash2 size={14}/></button></div></div>):<p className="small-muted">{t('newsEmpty')}</p>}</section></div>
}

function MobileBar(){const {t,go,page,user,lang,orders}=useShop();const pending=orders.filter(o=>o.seller===user?.id&&o.status!=='completed'&&o.status!=='cancelled').length;const items=nativeApp?[
 ['home',Home,nt(lang,'home')],['catalog',Layers,nt(lang,'catalog')],['seller',Store,nt(lang,'sell')],['chats',MessageCircle,nt(lang,'messages')],[user?'buyer':'auth',UserRound,nt(lang,'profile')]
 ]:[['home',Home,'home'],['catalog',Search,'catalog'],['cart',ShoppingCart,'cart'],[user?'buyer':'auth',UserRound,user?'profile':'login']];return <div className={'mobile-bar '+(nativeApp?'shods-native-bottom':'')}>{items.map(([path,Icon,label])=><button key={path} className={page===path?'current':''} aria-label={nativeApp?label:t(label)} onClick={()=>go(path)}><Icon size={21}/>{nativeApp&&path==='seller'&&pending>0&&<span className="shods-nav-notice">{pending>9?'9+':pending}</span>}<small>{nativeApp?label:t(label)}</small></button>)}</div>}
export default function App(){
 const [lang,setLang]=useState(()=>localStorage.getItem('shods_lang')||'uz');
 useEffect(()=>{document.documentElement.classList.toggle('shods-native',nativeApp);return()=>document.documentElement.classList.remove('shods-native')},[]);
 const [theme,setTheme]=useState(()=>localStorage.getItem('shods_theme')||'light');
 const [page,setPage]=useState('home');const [selectedId,setSelectedId]=useState(null);
 const [mode,setMode]=useState(()=>localStorage.getItem('shods_mode')||'buyer');
 const [installPrompt,setInstallPrompt]=useState(null);
 const [connectionError,setConnectionError]=useState('');
 const [items,setItems]=useState([]),[mine,setMine]=useState([]),[orders,setOrders]=useState([]),[reviews,setReviews]=useState([]),[tickets,setTickets]=useState([]),[favorites,setFavorites]=useState([]),[user,setUser]=useState(null),[cart,setCart]=useState(()=>{try{return JSON.parse(localStorage.getItem('shods_cart')||'[]')}catch{return []}}),[config,setConfig]=useState({institutions:[],faculties:[]}),[loading,setLoading]=useState(true),[notice,setNotice]=useState(''),[mobileMenu,setMobileMenu]=useState(false);
 const t=key=>tLang(lang,key);
 useEffect(()=>{const h=e=>{e.preventDefault();setInstallPrompt(e)};window.addEventListener('beforeinstallprompt',h);return ()=>window.removeEventListener('beforeinstallprompt',h)},[]);
 async function install(){if(!installPrompt)return;await installPrompt.prompt();setInstallPrompt(null)}
 useEffect(()=>{localStorage.setItem('shods_lang',lang);document.documentElement.lang=lang},[lang]);useEffect(()=>{localStorage.setItem('shods_theme',theme);document.documentElement.dataset.theme=theme},[theme]);useEffect(()=>{localStorage.setItem('shods_mode',mode)},[mode]);useEffect(()=>{localStorage.setItem('shods_cart',JSON.stringify(cart))},[cart]);
 function toast(message){setNotice(message);window.clearTimeout(window.__shodsToast);window.__shodsToast=setTimeout(()=>setNotice(''),4300)}
 function go(next,id){if(['seller','buyer','add','admin','chats','notifications'].includes(next)&&!user){setPage('auth');return}if(next==='admin'&&user?.role!=='admin')return toast(t('accessDenied'));if(next==='seller'||next==='add')setMode('seller');if(next==='buyer')setMode('buyer');setPage(next);setSelectedId(id||null);setMobileMenu(false);if(next==='auth'&&id==='register')window.location.hash='register';else if(window.location.hash)history.replaceState(null,'',location.pathname);window.scrollTo({top:0,behavior:'instant'})}
 async function refresh(){if(nativeApp){const health=await api('/health');if(!health?.capabilities?.android)throw Error('SERVER_ANDROID_VERSION_OUTDATED')}const initial=await api('/bootstrap');setItems(initial.items);setConfig({...initial.config,institutions:initial.institutions,faculties:initial.faculties});const auth=await api('/auth/me');setUser(auth.user);if(auth.user){const [my,orderData,ticketData,fav]=await Promise.all([api('/listings/mine'),api('/orders?type=both'),api('/support'),api('/favorites')]);setMine(my.items);setOrders(orderData.orders);setTickets(ticketData.tickets);setFavorites(fav.ids)}else{setMine([]);setOrders([]);setTickets([]);setFavorites([])}return auth.user}
 useEffect(()=>{refresh().then(()=>setConnectionError('')).catch(e=>{setConnectionError(e?.message||'NETWORK_ERROR');toast(t('errorNetwork'))}).finally(()=>setLoading(false))},[]);
 async function retryConnection(){setLoading(true);try{await refresh();setConnectionError('')}catch(e){setConnectionError(e?.message||'NETWORK_ERROR')}finally{setLoading(false)}}
 async function run(fn,message){try{const result=await fn();if(message)toast(message);return result}catch(e){toast(cleanError(e,t));return null}}
 async function login(payload){const result=await run(async()=>{await api('/auth/login',{method:'POST',body:payload});await refresh();setPage('buyer');window.scrollTo(0,0)},t('ok'));return result}
 async function register(payload){return run(async()=>{await api('/auth/register',{method:'POST',body:payload});await refresh();setPage('buyer');window.scrollTo(0,0)},t('saved'))}
 async function logout(){await run(async()=>{await api('/auth/logout',{method:'POST',body:{}});await refresh();setCart([]);go('home')},t('logout'))}
 function addCart(item){if(!user){go('auth');return toast(t('loginRequired'))}if(item.seller===user.id)return toast(t('ownItem'));if(item.stock<=0||!item.active)return toast(t('unavailable'));setCart(old=>{const found=old.find(o=>o.id===item.id);return found?old.map(x=>x.id===item.id?{...x,qty:Math.min(item.stock,x.qty+1)}:x):[...old,{id:item.id,qty:1}]});toast(t('addCart'))}
 async function toggleFavorite(id){if(!user)return go('auth');await run(async()=>{const r=await api('/favorites/'+id,{method:'POST',body:{}});setFavorites(r.ids)},t('saved'))}
 const context={t,lang,setLang,theme,setTheme,installPrompt,install,page,go,selectedId,items,mine,orders,reviews,setReviews,tickets,favorites,cart,setCart,user,mode,setMode,mobileMenu,setMobileMenu,config,loading,toast,refresh,run,login,register,logout,addCart,toggleFavorite};
 return <ShopContext.Provider value={context}><div className="app"><Header/>{loading?<div className="shell page-space"><div className="loading-screen"><Sparkles size={34}/><p>{t('dataLoading')}</p></div></div>:nativeApp&&connectionError?<NativeConnectionError reason={connectionError} onRetry={retryConnection}/>:<>{page==='home'&&(nativeApp?<NativeHomePage/>:<HomePage/>)}{page==='catalog'&&<CatalogPage/>}{page==='services'&&<CatalogPage servicesOnly/>}{page==='jobs'&&<JobsPage/>}{page==='news'&&<NewsPage/>}{page==='chats'&&<ChatsPage/>}{page==='notifications'&&<NotificationsPage/>}{page==='detail'&&<DetailPage/>}{page==='sellerPublic'&&<SellerPublicPage/>}{page==='cart'&&<CartPage/>}{page==='auth'&&<AuthPage/>}{page==='buyer'&&(user?<BuyerDashboard/>:<AuthPage/>)}{page==='seller'&&(user?<SellerDashboard/>:<AuthPage/>)}{page==='add'&&(user?<ListingEditor/>:<AuthPage/>)}{page==='ai'&&(nativeApp?<NativeAIPage/>:<AIPage/>)}{page==='support'&&<SupportPage/>}{page==='admin'&&<AdminPage/>}</>}<Footer/><MobileBar/>{notice&&<div role="status" className="toast"><CheckCircle2 size={20}/><span>{notice}</span><button onClick={()=>setNotice('')}><X size={16}/></button></div>}</div></ShopContext.Provider>
}
